    [SuppressMessage("Microsoft.StyleCop.CSharp.DocumentationRules", "SA1600:ElementsMustBeDocumented")]
    public class AdminSecurityCodeService : IAdminSecurityCodeService
    {
        private readonly IAdminSecurityCodeDataAccess _reportRepository;

        public AdminSecurityCodeService()
            : this(null)
        {
        }

        public AdminSecurityCodeService(IAdminSecurityCodeDataAccess reportRepository)
        {
            this._reportRepository = reportRepository ?? new AdminSecurityCodeDataAccess();
        }

        public List<CustomerInfo> GetUserList(GetUserListCriteria criteria)
        {
            try
            {
                var rawData = this._reportRepository.GetUserList(criteria);
                var userList = new List<CustomerInfo>();

                var mainAccountGroups = rawData.GroupBy(data =>
                    new
                    {
                        data.CustId,
                        data.UserName,
                        data.RoleId
                    });

                foreach (var mainAccountGroup in mainAccountGroups)
                {
                    var mainAccount = new CustomerInfo
                    {
                        UserId = CastAide.AsInt32(mainAccountGroup.Key.CustId),
                        UserName = CastAide.AsString(mainAccountGroup.Key.UserName),
                        RoleId = CastAide.AsInt32(mainAccountGroup.Key.RoleId),
                        SecurityCode = string.Empty,
                        SubAccounts = new List<CustomerInfo>()
                    };

                    foreach (var data in mainAccountGroup)
                    {
                        var info = new CustomerInfo
                        {
                            UserId = CastAide.AsInt32(data.SubCustId),
                            UserName = CastAide.AsString(data.SubUserName),
                            SecurityCode = string.Empty,
                            RoleId = CastAide.AsInt32(data.RoleId)
                        };

                        mainAccount.SubAccounts.Add(info);
                    }

                    userList.Add(mainAccount);
                }

                return userList;
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }

            return null;
        }

        public Result UpdateUsersSecurityCode(List<CustomerInfo> criteria)
        {
            try
            {
                var result = new Result
                {
                    ErrorMessage = string.Empty
                };

                foreach (var userInfo in criteria)
                {
                    if (!userInfo.IsSelected || !userInfo.IsValid)
                    {
                        continue;
                    }

                    var updateResult = this.ResetSecurityCode(new ResetSecurityCodeCriteria
                    {
                        IP = HttpContext.Current.Request.UserHostAddress,
                        Userid = AppSession.AccId,
                        Custid = userInfo.UserId,
                        Securitycode = userInfo.SecurityHashCode,
                        IsForcedChangeSecurityCode = true,
                        RoleId = userInfo.RoleId,
                        IsSubAccount = userInfo.IsSubAccount
                    });

                    if (updateResult != null && updateResult.ErrorCode > 0)
                    {
                        result.ErrorCode = 1;
                        result.ErrorMessage += updateResult.ErrorMessage + "\n";
                    }

                    System.Threading.Thread.Sleep(500);
                }

                return result;
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }

            return null;
        }

        private Result ResetSecurityCode(ResetSecurityCodeCriteria criteria)
        {
            try
            {
                Hashtable outputParams = new Hashtable();
                this._reportRepository.ResetSecurityCode(criteria, ref outputParams);
                return new Result
                {
                    ErrorCode = CastAide.AsInt32(outputParams["errcode"]),
                    ErrorMessage = CastAide.AsString(outputParams["errmsg"])
                };
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }

            return null;
        }

        public IList<CustomerInfo> ValidateCustomers(HttpPostedFileBase fileUploaded)
        {
            var result = new List<CustomerInfo>();
            try
            {
                var dtUsers = new DataTable();
                HSSFWorkbook hssfworkbook = new HSSFWorkbook(fileUploaded.InputStream);
                ISheet sheet = hssfworkbook.GetSheetAt(0);
                IEnumerator rows = sheet.GetRowEnumerator();
                dtUsers.Columns.Add("No");
                dtUsers.Columns.Add("User");
                dtUsers.Columns.Add("Security Code");

                var users = string.Empty;

                while (rows.MoveNext())
                {
                    IRow row = (HSSFRow)rows.Current;
                    DataRow dr = dtUsers.NewRow();
                    var count = 0;
                    for (int i = 0; i < row.LastCellNum; i++)
                    {
                        ICell cell = row.GetCell(i);
                        if (cell != null)
                        {
                            switch (cell.CellType)
                            {
                                case CellType.Numeric:
                                    dr[i + 1] = cell.NumericCellValue;
                                    break;
                                default:
                                    try
                                    {
                                        if (string.IsNullOrEmpty(cell.StringCellValue))
                                        {
                                            count++;
                                            break;
                                        }

                                        dr[i + 1] = cell.StringCellValue;

                                        break;
                                    }
                                    catch (Exception ex)
                                    {
                                        LogExtensions.ExceptionHandler(ex);
                                        throw new Exception("Input invalid at row " + (row.RowNum + 1) + " cell " + (i + 1) + "!");
                                    }
                            }
                        }
                        else
                        {
                            count++;
                        }
                    }

                    if (count != row.LastCellNum && row.RowNum > 0)
                    {
                        dr[0] = row.RowNum + 1;
                        dtUsers.Rows.Add(dr);
                        users += string.Format("{0},", dr[1]);
                    }

                }
                var criteria = new GetUserListCriteria();
                criteria.ListUserName = users;
                var validUsers = GetUserList(criteria);
                if (validUsers != null && validUsers.Count > 0)
                {
                    var userLength = validUsers.Count;
                    for (var i = 0; i < userLength; i++)
                    {
                        var selSecurityCode = (from u in dtUsers.AsEnumerable()
                                               where u.Field<string>("user").ToLower().Equals(validUsers[i].UserName.ToLower())
                                               select u.Field<string>("Security Code")).FirstOrDefault();
                        validUsers[i].SecurityCode = selSecurityCode;

                        var subAccountLength = validUsers[i].SubAccounts.Count;
                        for (var j = 0; j < subAccountLength; j++)
                        {
                            validUsers[i].SubAccounts[j].SecurityCode = selSecurityCode;
                        }
                    }

                    return validUsers;
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }
    }
